import { jsPDF } from "jspdf";

(function (jsPDFAPI) {
 var font = '';
 var callAddFont = function () {
  this.addFileToVFS('century-gothic-sans-font-normal.ttf', font);
  this.addFont('century-gothic-sans-font-normal.ttf', 'century-gothic-sans-font', 'normal');
 };
 jsPDF.API.events.push(['addFonts', callAddFont])
})(jsPDF.API)
